import org.junit.Test;
import static org.junit.Assert.*;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class CommentsConfigurationTest {

    @Test
    public void constructor_test() {
        CommentsConfiguration config = new CommentsConfiguration();
        assertNotNull(config.comments);
    }

    @Test
    public void constructor_with_comments_test() {
        Map<String, List<String>> comments = new HashMap<>();
        comments.put("key", Arrays.asList("line1", "line2"));
        CommentsConfiguration config = new CommentsConfiguration(comments);
        assertEquals(comments, config.comments);
    }

    @Test
    public void setComment_emptyPath_test() {
        CommentsConfiguration config = new CommentsConfiguration();
        String emptyPath = "";
        String[] commentLines = {};
        config.setComment(emptyPath, commentLines);
        assertNotNull(config.comments.get(emptyPath));
    }

    @Test
    public void setComment_singleLineWithoutMarker_test() {
        CommentsConfiguration config = new CommentsConfiguration();
        String path = "path";
        String commentLine = "\n";
        String[] commentLines = {commentLine};
        config.setComment(path, commentLines);
        assertEquals(Collections.singletonList(commentLine), config.comments.get(path));
    }

    @Test
    public void setComment_multipleLinesWithMarker_test() {
        CommentsConfiguration config = new CommentsConfiguration();
        String path = "path";
        String[] commentLines = {"line1", "line2"};
        config.setComment(path, commentLines);
        assertEquals(Arrays.asList("line1", "line2"), config.comments.get(path));
    }

    @Test
    public void setComment_multiplePaths_test() {
        CommentsConfiguration config = new CommentsConfiguration();
        String path1 = "path1";
        String[] commentLines1 = {"line1", "line2"};
        config.setComment(path1, commentLines1);
        String path2 = "path2";
        String[] commentLines2 = {"line3", "line4"};
        config.setComment(path2, commentLines2);
        assertEquals(Arrays.asList(commentLines1), config.comments.get(path1));
    }

    @Test
    public void getAllComments_emptyMap_test() {
        CommentsConfiguration config = new CommentsConfiguration();
        Map<String, List<String>> emptyMap = Collections.emptyMap();
        config.comments = emptyMap;
        assertTrue(config.getAllComments().isEmpty());
    }

    @Test
    public void getAllComments_nonEmptyMap_test() {
        CommentsConfiguration config = new CommentsConfiguration();
        Map<String, List<String>> comments = new HashMap<>();
        comments.put("key1", Arrays.asList("line11", "line12"));
        comments.put("key2", Arrays.asList("line21", "line22"));
        config.comments = Collections.unmodifiableMap(comments);
        assertNotNull(config.getAllComments());
    }

}
